    /// R20-010(2): custody at each pair-setup step — the
    /// R19-014 probes ran spawn/read/parse/stat `.expect`s
    /// with no guard (a panic stranded the pair). Two
    /// phases: (a) guards at spawn (publisher) and parse
    /// (stranger), then an injected failure → unwind retires
    /// both; (b) the realistic shape — the publisher dies
    /// before its stat read (`.expect("publisher visible")`
    /// panics) → unwind retires the stranger through its
    /// guard. Observe-before-cleanup (evidence, explicit
    /// retire of leftovers, then the verdict — RED runs stay
    /// clean). R21 holistic: self-grouped spawns, Result
    /// setups (a read/parse/stat failure retires the
    /// unknown-sleeper group before failing loud), gated
    /// tails (never ungated kill + blocking wait), bounded
    /// phase-(b) reap. Durations 925/926 are unique to this
    /// test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pair_setup_failure_retires_guarded_fixtures() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        // Phase (a): injected failure after setup.
        let mut publisher = spawn_self_grouped_publisher("925", "wait", &[]);
        let pubpid = publisher.id() as libc::pid_t;
        // R21-009-pair-setup: the setup is a Result — a
        // read/parse/stat failure retires the
        // unknown-sleeper group BEFORE failing loud (never a
        // bare `.expect` past the unreaped leader).
        let setup: Result<((libc::pid_t, u64), u64), String> = (|| {
            let mut line = String::new();
            std::io::BufReader::new(
                publisher
                    .stdout
                    .take()
                    .ok_or_else(|| "publisher stdout missing".to_string())?,
            )
            .read_line(&mut line)
            .map_err(|error| format!("stranger pair unreadable: {error}"))?;
            let pair = try_parse_published_pair(line.trim(), "stranger publication")?;
            let pubtick = match proc_starttime(pubpid) {
                Ok(Some(tick)) => tick,
                Ok(None) => return Err("publisher gone pre-guard".to_string()),
                Err(error) => return Err(format!("publisher stat unreadable: {error}")),
            };
            Ok((pair, pubtick))
        })();
        let ((stranger, stick), pubtick_a) = match setup {
            Ok(ok) => ok,
            Err(cause) => {
                let status = retire_unparsed_publisher_group(&mut publisher);
                panic!("phase (a) setup failed ({cause}) — group retired ({status:?})");
            }
        };
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            // Custody at each step (the fix): publisher at
            // spawn, stranger at parse — the injected
            // failure unwinds through both.
            let _publisher_guard = FixtureGuard::new(pubpid);
            let _stranger_guard = FixtureGuard::new_expected(stranger, stick);
            panic!("R20010 injected post-setup failure");
        }));
        let gone_pub_a = await_proc_gone_reaping(pubpid, pubtick_a, Duration::from_secs(5));
        let gone_str_a = await_proc_gone_reaping(stranger, stick, Duration::from_secs(5));
        let _ = kill_tick_gated(stranger, stick);
        // R21-010-tails: gated retire + WNOHANG-only reap
        // (never the ungated kill + blocking wait — the
        // number may host a replacement now).
        let _ = retire_tick_gated_audit_child(pubpid, pubtick_a);
        assert!(failed.is_err(), "phase (a) must inject the failure");
        assert!(
            gone_pub_a && gone_str_a,
            "phase (a) unwind must retire the pair"
        );
        // Phase (b): publisher dies before its stat read.
        let mut publisher_b = spawn_self_grouped_publisher("926", "wait", &[]);
        let pubpid_b = publisher_b.id() as libc::pid_t;
        let setup_b: Result<((libc::pid_t, u64), u64), String> = (|| {
            let mut line_b = String::new();
            std::io::BufReader::new(
                publisher_b
                    .stdout
                    .take()
                    .ok_or_else(|| "publisher stdout missing".to_string())?,
            )
            .read_line(&mut line_b)
            .map_err(|error| format!("stranger pair unreadable: {error}"))?;
            let pair = try_parse_published_pair(line_b.trim(), "stranger publication")?;
            let pubtick = match proc_starttime(pubpid_b) {
                Ok(Some(tick)) => tick,
                Ok(None) => return Err("publisher gone pre-guard".to_string()),
                Err(error) => return Err(format!("publisher stat unreadable: {error}")),
            };
            Ok((pair, pubtick))
        })();
        let ((stranger_b, stick_b), pubtick_b) = match setup_b {
            Ok(ok) => ok,
            Err(cause) => {
                let status = retire_unparsed_publisher_group(&mut publisher_b);
                panic!("phase (b) setup failed ({cause}) — group retired ({status:?})");
            }
        };
        let failed_b = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _publisher_guard = FixtureGuard::new(pubpid_b);
            let _stranger_guard = FixtureGuard::new_expected(stranger_b, stick_b);
            assert!(kill_tick_gated(pubpid_b, pubtick_b));
            // R21-010-tails: bounded WNOHANG reap (never a
            // blocking wait — same µs behavior on the
            // SIGKILLed child, loud instead of wedged on the
            // impossible).
            let start = Instant::now();
            let reaped = loop {
                let mut status = 0;
                // SAFETY: WNOHANG reap of our own killed
                // child; never blocks.
                let got = unsafe { libc::waitpid(pubpid_b, &mut status, libc::WNOHANG) };
                if got == pubpid_b {
                    break true;
                }
                if got < 0 {
                    let error = std::io::Error::last_os_error();
                    if error.kind() == std::io::ErrorKind::Interrupted {
                        continue;
                    }
                    break false;
                }
                if start.elapsed() >= Duration::from_secs(5) {
                    break false;
                }
                std::thread::sleep(Duration::from_millis(1));
            };
            assert!(reaped, "publisher reaps");
            let _ = proc_starttime(pubpid_b)
                .expect("publisher stat readable")
                .expect("publisher visible");
        }));
        let gone_str_b = await_proc_gone_reaping(stranger_b, stick_b, Duration::from_secs(5));
        let _ = kill_tick_gated(stranger_b, stick_b);
        let _ = retire_tick_gated_audit_child(pubpid_b, pubtick_b);
        assert!(failed_b.is_err(), "phase (b) stat must fail");
        assert!(gone_str_b, "phase (b) unwind must retire the stranger");
    }

    /// R21-007 + R21-010-tails + R21-009-pair-setup (holistic —
    /// ONE test): every post-birth producer step fails prompt,
    /// loud, and discharged; the receiver setup retires the
    /// unknown-sleeper group on pre-parse failure; the
    /// pair-setup tails never murder or steal planted
    /// replacements. Publisher cells (pause/stat/comm/tick/
    /// wait/epipe): each fresh self-grouped spawn must exit 2
    /// promptly (≪ its sleep) with the group ESRCH-empty (the
    /// sleeper retired by the publisher's own guard — never
    /// orphaned). Receiver cells (eof/mangle): a pre-transmit
    /// failure must surface as PROMPT EOF (never wedge the
    /// read on the held pipe) and a torn pair must fail loud
    /// with the parse cause — both with the unknown-sleeper
    /// group retired (zombie-leader pin for eof, live-leader
    /// pin for mangle). Pre-fix RED: pause/epipe strand the
    /// sleep (group nonempty), the fault hook is ignored
    /// (hangs in the wait tail), and the bare kill+reap shape
    /// strands the unknown sleeper. Durations 933-941 and 951
    /// are unique to this test.
    /// R22-015: pub-cell judge (extracted from the
    /// run_pub_cell closure so the regression executes the
    /// same step): verdict FIRST (hung/stranded/post_empty
    /// — a failed verdict panics immediately WITHOUT
    /// touching stderr, since a stranded writer would wedge
    /// any drain for its whole lifetime), THEN the bounded
    /// stderr drain (nonblocking + deadline + cap —
    /// defense-in-depth: writers SHOULD be dead now),
    /// then the diagnostic asserts (promptness/code/marker)
    /// with the drained content.
    #[cfg(target_arch = "x86_64")]
    fn judge_pub_cell(
        step: &str,
        elapsed: Duration,
        outcome: Option<(std::process::ExitStatus, bool, bool)>,
        stderr_pipe: Option<std::process::ChildStderr>,
        marker: &str,
    ) {
        let (status, stranded, post_empty) = outcome.unwrap_or_else(|| {
            panic!(
                "PUB-{step}: publisher hung (fault ignored?) after {elapsed:?} \
                 (stderr undrained — verdict-first)"
            )
        });
        assert!(
            !stranded,
            "PUB-{step}: group must be ESRCH-empty (stranded sleeper; drain refused)"
        );
        assert!(
            post_empty,
            "PUB-{step}: group must prove ESRCH-empty after retire (squatter?; drain refused)"
        );
        // R23-018: 5 s idle + 60 s overall (dribble) ceilings.
        let err = drain_pipe_bounded(
            stderr_pipe,
            Duration::from_secs(5),
            Duration::from_secs(60),
            step,
        );
        assert!(
            elapsed < Duration::from_secs(5),
            "PUB-{step}: must fail promptly, took {elapsed:?}\nstderr: {err}"
        );
        assert_eq!(
            status.code(),
            Some(2),
            "PUB-{step}: must exit 2, got {status:?}\nstderr: {err}"
        );
        assert!(
            err.contains(marker),
            "PUB-{step}: stderr must name the failed step ({marker:?}), got {err:?}"
        );
    }

    /// R22-015: bounded pipe drain (nonblocking + deadline +
    /// 1MB cap) — defense-in-depth for diagnostic reads
    /// after judged-empty groups (a lingering writer wedges
    /// an unbounded `read_to_string` for the writer's whole
    /// lifetime). EOF before the deadline ⟹ content;
    /// still-open past the deadline ⟹ loud wedge-panic (a
    /// writer survived the verdict?! — with a partial
    /// preview); past 1MB ⟹ stops appending (drains on to
    /// EOF-or-deadline, discarding) and marks [TRUNCATED].
    /// `None` ⟹ empty. R23-018: `overall` is the SECOND
    /// ceiling — the idle deadline fires only on WouldBlock,
    /// so a steady dribble (bytes every wake-up, EOF never)
    /// would hang past it; flowing bytes past `overall` ⟹
    /// loud drain-corrupt panic (distinct attribution from
    /// the idle wedge AND from probe-death).
    #[cfg(target_arch = "x86_64")]
    fn drain_pipe_bounded(
        pipe: Option<std::process::ChildStderr>,
        timeout: Duration,
        overall: Duration,
        what: &str,
    ) -> String {
        use std::io::Read as _;
        use std::os::unix::io::AsRawFd as _;
        const CAP: usize = 1024 * 1024;
        let Some(mut pipe) = pipe else {
            return String::new();
        };
        // ChildStderr has no set_nonblocking — fcntl it
        // (our own pipe — staging-infallible).
        // SAFETY: fcntl O_NONBLOCK on our own pipe fd only.
        let flags = unsafe { libc::fcntl(pipe.as_raw_fd(), libc::F_GETFL) };
        assert!(flags >= 0, "PUB-{what}: fcntl F_GETFL failed");
        let set = unsafe { libc::fcntl(pipe.as_raw_fd(), libc::F_SETFL, flags | libc::O_NONBLOCK) };
        assert_eq!(set, 0, "PUB-{what}: fcntl O_NONBLOCK failed");
        let mut buf: Vec<u8> = Vec::new();
        let mut total: usize = 0;
        let mut capped = false;
        let end = Instant::now() + timeout;
        // R23-018: overall (dribble) ceiling — checked on
        // EVERY flowing read (the idle deadline below only
        // fires on WouldBlock, which a steady dribble never
        // produces).
        let end_overall = Instant::now() + overall;
        loop {
            let mut chunk = [0u8; 8192];
            match pipe.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    total += n;
                    if buf.len() < CAP {
                        let room = CAP - buf.len();
                        buf.extend_from_slice(&chunk[..n.min(room)]);
                    } else {
                        capped = true;
                    }
                    if Instant::now() >= end_overall {
                        let preview =
                            String::from_utf8_lossy(&buf[..buf.len().min(500)]).into_owned();
                        panic!(
                            "PUB-{what}: stderr drain exceeded overall {overall:?} ({total} bytes, \
                             EOF never arrived — drain-corrupt, a writer survived?!) — \
                             partial: {preview:?}",
                        );
                    }
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    if Instant::now() >= end {
                        let preview =
                            String::from_utf8_lossy(&buf[..buf.len().min(500)]).into_owned();
                        panic!(
                            "PUB-{what}: stderr drain wedged past {timeout:?} (a writer \
                             survived the verdict?!) — partial ({total} bytes): {preview:?}",
                        );
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                Err(error) => panic!("PUB-{what}: stderr drain failed: {error}"),
            }
        }
        let mut out = String::from_utf8_lossy(&buf).into_owned();
        if capped {
            out.push_str("\n[TRUNCATED at 1MB]");
        }
        out
    }

    /// R23-018: a steadily dribbling writer (bytes every
    /// wake-up, EOF never) must trip the OVERALL ceiling
    /// with drain-corrupt attribution (the idle deadline
    /// alone never fires — no WouldBlock). Shell dribbler
    /// (1 byte/100ms on stderr, never EOFs) + 5 s idle /
    /// 2 s overall: the drain must panic ~2s citing
    /// drain-corrupt (pre-fix it hung forever). Cleanup
    /// kills the dribbler. No fixture durations (sh, no
    /// sleep).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn drain_pipe_dribble_trips_overall_ceiling() {
        use std::time::{Duration, Instant};
        let message_of = |payload: Box<dyn std::any::Any + Send>| {
            payload
                .downcast_ref::<String>()
                .map(String::as_str)
                .or_else(|| payload.downcast_ref::<&str>().copied())
                .unwrap_or("")
                .to_string()
        };
        let mut dribbler = std::process::Command::new("sh")
            .arg("-c")
            .arg("while true; do printf x >&2; sleep 0.1; done")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("dribbler spawns");
        let stderr_pipe = dribbler.stderr.take();
        let start = Instant::now();
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            drain_pipe_bounded(
                stderr_pipe,
                Duration::from_secs(5),
                Duration::from_secs(2),
                "r23018",
            );
        }));
        let elapsed = start.elapsed();
        // Cleanup FIRST: the dribbler outlives the verdict.
        let _ = dribbler.kill();
        let _ = dribbler.wait();
        assert!(
            elapsed < Duration::from_secs(10),
            "dribble must trip the ceiling promptly (pre-fix: forever)"
        );
        match outcome {
            Err(payload) => assert!(
                message_of(payload).contains("drain-corrupt"),
                "dribble must cite drain-corrupt (distinct from wedge/probe-death)"
            ),
            Ok(_) => panic!("dribble past the overall ceiling must panic (never return)"),
        }
    }

    /// R22-015: the pub-cell judge pins verdict-first +
    /// bounded diagnostics. Leg 1 (denied-cleanup shape: a
    /// failed outcome + a LIVE stderr writer): must panic
    /// on the VERDICT fast (<5s — the pipe is never
    /// touched). Leg 2 (verdict-lied shape: a success
    /// outcome + a LIVE writer): the bounded drain must
    /// wedge-panic (~5s, loud, with a partial preview —
    /// never a silent 900s). Leg 3 (positive: success +
    /// EOF pipe with the marker): returns normally. Writers
    /// print the marker then `exec sleep` (one process —
    /// cleanup via the held handle, no orphans). RED (old
    /// shape: leg 1 drains 7s then judges (time fails);
    /// leg 2 drains to EOF and passes silent (no panic)).
    /// Durations 7 and 8 are unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn judge_pub_cell_verdict_first_and_bounded() {
        use std::panic::AssertUnwindSafe;
        let exit2 = || {
            std::process::Command::new("sh")
                .arg("-c")
                .arg("exit 2")
                .status()
                .expect("exit-2 fabricates")
        };
        let message_of = |payload: Box<dyn std::any::Any + Send>| {
            payload
                .downcast_ref::<String>()
                .map(String::as_str)
                .or_else(|| payload.downcast_ref::<&str>().copied())
                .unwrap_or("")
                .to_string()
        };
        // Leg 1: failed verdict + live writer ⟹ fast
        // stranded-panic (verdict-first — no drain).
        let mut writer1 = std::process::Command::new("sh")
            .arg("-c")
            .arg("echo PUBMARK >&2; exec sleep 7")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("writer1 spawns");
        let mut _w1guard = FixtureGuard::new(writer1.id() as libc::pid_t);
        let pipe1 = writer1.stderr.take();
        let start = Instant::now();
        let verdict1 = std::panic::catch_unwind(AssertUnwindSafe(|| {
            judge_pub_cell(
                "t",
                Duration::from_millis(100),
                Some((exit2(), true, false)),
                pipe1,
                "PUBMARK",
            )
        }));
        let leg1_time = start.elapsed();
        let _ = writer1.kill();
        let _ = writer1.wait();
        _w1guard.disarm();
        let message1 = match verdict1 {
            Ok(()) => panic!("leg 1 must panic (stranded verdict)"),
            Err(payload) => message_of(payload),
        };
        assert!(
            message1.contains("stranded"),
            "leg 1 must cite the verdict, got: {message1}"
        );
        assert!(
            leg1_time < Duration::from_secs(5),
            "leg 1 must fail fast (verdict-first — no drain), took {leg1_time:?}"
        );
        // Leg 2: success verdict + live writer ⟹ bounded
        // wedge-panic (~5s, loud — never silent, never
        // 900s).
        let mut writer2 = std::process::Command::new("sh")
            .arg("-c")
            .arg("echo PUBMARK >&2; exec sleep 8")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("writer2 spawns");
        let mut _w2guard = FixtureGuard::new(writer2.id() as libc::pid_t);
        let pipe2 = writer2.stderr.take();
        let start = Instant::now();
        let verdict2 = std::panic::catch_unwind(AssertUnwindSafe(|| {
            judge_pub_cell(
                "t",
                Duration::from_millis(100),
                Some((exit2(), false, true)),
                pipe2,
                "PUBMARK",
            )
        }));
        let leg2_time = start.elapsed();
        let _ = writer2.kill();
        let _ = writer2.wait();
        _w2guard.disarm();
        let message2 = match verdict2 {
            Ok(()) => panic!("leg 2 must panic (wedged drain)"),
            Err(payload) => message_of(payload),
        };
        assert!(
            message2.contains("wedged"),
            "leg 2 must cite the wedge, got: {message2}"
        );
        assert!(
            leg2_time >= Duration::from_secs(5) && leg2_time < Duration::from_secs(30),
            "leg 2 must bound (~5s deadline), took {leg2_time:?}"
        );
        // Leg 3: success verdict + EOF pipe with the marker
        // ⟹ returns normally.
        let mut writer3 = std::process::Command::new("sh")
            .arg("-c")
            .arg("echo PUBMARK >&2")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .expect("writer3 spawns");
        let mut _w3guard = FixtureGuard::new(writer3.id() as libc::pid_t);
        let pipe3 = writer3.stderr.take();
        judge_pub_cell(
            "t",
            Duration::from_millis(100),
            Some((exit2(), false, true)),
            pipe3,
            "PUBMARK",
        );
        let _ = writer3.wait();
        _w3guard.disarm();
    }

    #[test]
    #[cfg(target_arch = "x86_64")]
    fn pair_setup_holistic_retirement() {
        use std::time::{Duration, Instant};
        // One cell runner (env cells + the real-path EPIPE
        // cell share it): bounded wait, observe-before-cleanup
        // (sample group, retire leftovers, drain stderr —
        // post-cleanup so a stranded sleeper cannot wedge the
        // read), then judge code + step-fidelity + promptness
        // + group-empty.
        let run_pub_cell =
            |step: &str, secs: &str, envs: &[(&str, &str)], drop_read: bool, marker: &str| {
                let mut publisher = spawn_self_grouped_publisher(secs, "wait", envs);
                if drop_read {
                    drop(publisher.stdout.take());
                }
                let pubpid = publisher.id() as libc::pid_t;
                // R23-011: TREE guard at spawn (this cell never
                // sights the stranger — a panic before the judge
                // must not orphan the unsighted sleep).
                let mut _pguard = PublisherTreeGuard::new(pubpid);
                // Birth tick at spawn (live-unreaped — nothing
                // reaped yet — so this first read names OUR
                // birth; every decision below re-verifies it).
                // R22-002: decide while pinned, reap after —
                // the old shape reaped via try_wait FIRST and
                // then killpg'd the unpinned number (a leader
                // that exited during the observation was
                // already reaped (pin released) and the killpg
                // murdered whoever recycled it).
                let pubtick = proc_starttime(pubpid)
                    .unwrap_or_else(|error| panic!("PUB-{step}: publisher stat readable: {error}"))
                    .unwrap_or_else(|| panic!("PUB-{step}: publisher visible"));
                // Leader-state poll (pin-verified every poll —
                // tick mismatch/gone is an invariant violation
                // (nothing reaps yet — no guards on the
                // publisher, no handle waits yet, the probe
                // never waits, bare waitpid(-1) audited
                // absent); unreadable polls through (transient
                // outage) and fails loud only when persistent
                // (unverifiable — refuse to kill blindly).
                let start = Instant::now();
                let hung = loop {
                    match proc_starttime(pubpid) {
                        Ok(Some(now)) if now == pubtick => {
                            if proc_state(pubpid) == Some('Z') {
                                break false;
                            }
                        }
                        Ok(_) => panic!(
                            "PUB-{step}: leader reaped before observation \
                             (pin violated — impossible: nothing reaps yet)"
                        ),
                        Err(_) => {}
                    }
                    if start.elapsed() >= Duration::from_secs(10) {
                        match proc_starttime(pubpid) {
                            Ok(Some(now)) if now == pubtick => break true,
                            Ok(_) => panic!(
                                "PUB-{step}: leader reaped before observation \
                                 (pin violated — impossible: nothing reaps yet)"
                            ),
                            Err(error) => panic!(
                                "PUB-{step}: leader unobservable for 10s \
                                 (outage?): {error} — refusing to kill blindly"
                            ),
                        }
                    }
                    std::thread::sleep(Duration::from_millis(1));
                };
                let elapsed = start.elapsed();
                // Both branches killpg with the leader unreaped
                // (pin held — re-verified inside) and reap
                // through the handle only after the decision.
                let outcome = if hung {
                    let _ = retire_hung_publisher_group(&mut publisher, pubpid, pubtick);
                    None
                } else {
                    Some(retire_exited_publisher_group(
                        &mut publisher,
                        pubpid,
                        pubtick,
                    ))
                };
                _pguard.disarm();
                judge_pub_cell(step, elapsed, outcome, publisher.stderr.take(), marker);
            };
        // Real pause-timeout path (absent flag + short
        // deadline hook — the 30s default would hang RED).
        let pause_flag = format!("/tmp/scopebase-r21holistic-absent-{}", std::process::id());
        run_pub_cell(
            "pause",
            "933",
            &[
                ("SCOPEBASE_PUBLISHER_PAUSE_FILE", pause_flag.as_str()),
                ("SCOPEBASE_PUBLISHER_PAUSE_TIMEOUT_MS", "200"),
            ],
            false,
            "pause flag never appeared",
        );
        // Fault-hook cells (each forced error branch post-spawn).
        for (step, secs) in [
            ("stat", "934"),
            ("comm", "935"),
            ("tick", "936"),
            ("wait", "937"),
        ] {
            run_pub_cell(
                step,
                secs,
                &[("SCOPEBASE_PUBLISHER_FAULT_STEP", step)],
                false,
                &format!("fault: {step}"),
            );
        }
        // Real EPIPE path (no env): the read end drops at once —
        // the transmit write must fail loud, not panic, and the
        // sleep must be retired, not stranded.
        run_pub_cell("epipe", "938", &[], true, "stdout broken");
        // Receiver pre-parse-failure runner: the setup shape
        // under test — try-parse, and on failure group-retire
        // BEFORE any reap (the leader is still unreaped, so
        // the killpg is pinned), then loud with the cause.
        // Observe-before-cleanup (sample group, retire
        // leftovers), then judge cause + group-empty.
        let run_recv_fail = |step: &str,
                             publisher: &mut std::process::Child,
                             pubpid: libc::pid_t,
                             line: &str,
                             cause_sub: &str| {
            let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                match try_parse_published_pair(line, "holistic publication") {
                    Ok(_) => panic!("RECV-{step}: torn pair must not parse"),
                    Err(cause) => {
                        let status = retire_unparsed_publisher_group(publisher);
                        panic!("RECV-{step}: setup failed ({cause}) — group retired ({status:?})");
                    }
                }
            }));
            // R22-002: the post-reap leftover killpg is
            // DELETED (the leader is reaped — pin released —
            // so custody of the group is unprovable and a
            // killpg would be unpinned murder-bait; the
            // pinned killpg already ran inside the retire).
            // Anything still present (squatter, D-state, slow
            // settle) fails the empty assert below — loud,
            // never certified. RED/neuter runs may strand the
            // unknown sleeper (unkillable-by-us post-reap: no
            // tick to gate on, no pin to killpg under) and
            // leak the leader zombie to process exit
            // (accepted — zombies auto-reap at exit; live
            // strays are the suite's concern, and GREEN runs
            // never reach here non-empty).
            let empty = await_group_empty(pubpid, Duration::from_millis(500));
            let error = failed
                .err()
                .unwrap_or_else(|| panic!("RECV-{step}: must fail loud (the torn pair parsed?!)"));
            let message = error.downcast_ref::<String>().cloned().unwrap_or_default();
            assert!(
                message.contains(cause_sub),
                "RECV-{step}: cause must name the failure ({cause_sub:?}), got {message:?}"
            );
            assert!(
                empty,
                "RECV-{step}: group must be ESRCH-empty (unknown sleeper stranded)"
            );
        };
        // RECV-eof: the publisher fails pre-transmit (real
        // pause path) — the read must see EOF PROMPTLY (the
        // publisher's guard closed the pipe; pre-fix the read
        // wedged the full sleep) and the zombie-leader group
        // must retire with the loud parse cause.
        {
            use std::io::BufRead as _;
            let mut publisher = spawn_self_grouped_publisher(
                "939",
                "wait",
                &[
                    ("SCOPEBASE_PUBLISHER_PAUSE_FILE", pause_flag.as_str()),
                    ("SCOPEBASE_PUBLISHER_PAUSE_TIMEOUT_MS", "200"),
                ],
            );
            let pubpid = publisher.id() as libc::pid_t;
            // R23-011: TREE guard at spawn (the eof stranger
            // stays unknown throughout — a panic must not
            // orphan its sleep).
            let mut _pguard = PublisherTreeGuard::new(pubpid);
            let start = Instant::now();
            let mut line = String::new();
            let bytes = std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
                .read_line(&mut line)
                .expect("eof readable");
            let elapsed = start.elapsed();
            assert_eq!(bytes, 0, "RECV-eof: failed publisher must transmit nothing");
            assert!(
                elapsed < Duration::from_secs(5),
                "RECV-eof: EOF must arrive promptly, took {elapsed:?}"
            );
            run_recv_fail("eof", &mut publisher, pubpid, &line, "missing pid");
            _pguard.disarm();
        }
        // RECV-mangle: real transmit, test-side torn pair
        // (tick dropped — the torn-write class) — the
        // live-leader group must retire with the loud parse
        // cause (the stranger stays unknown throughout).
        {
            use std::io::BufRead as _;
            let mut publisher = spawn_self_grouped_publisher("940", "wait", &[]);
            let pubpid = publisher.id() as libc::pid_t;
            // R23-011: TREE guard at spawn (the torn pair keeps
            // the stranger unknown throughout — a panic must
            // not orphan its sleep).
            let mut _pguard = PublisherTreeGuard::new(pubpid);
            let mut line = String::new();
            std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
                .read_line(&mut line)
                .expect("pair readable");
            let mangled = line
                .split_whitespace()
                .next()
                .unwrap_or_default()
                .to_string();
            assert!(!mangled.is_empty(), "RECV-mangle: pair must transmit");
            run_recv_fail("mangle", &mut publisher, pubpid, &mangled, "missing tick");
            _pguard.disarm();
        }
        // TAIL-live-plant: the pair-setup tail must not murder
        // a recycled occupant — retire OUR pair, plant a live
        // replacement on the freed publisher number, run the
        // tail with the STALE tick → the replacement is spared
        // (live, same birth, still our unreaped child) and the
        // tail is prompt (never a blocking wait). Pre-fix RED:
        // the ungated `publisher.kill()` murders the plant.
        // (Helper fn: a vacuous plant skips only its cell.)
        tail_live_plant_cell();
        // TAIL-zombie-plant: the tail must not STEAL a
        // recycled occupant's status — same staging, but the
        // plant settles to an unreaped zombie before the tail
        // runs with the stale tick → WE still reap it (the
        // tail's WNOHANG never fires on mismatch). Pre-fix
        // RED: the blocking `publisher.wait()` reaps the
        // plant's status through the unaware handle.
        tail_zombie_plant_cell();
    }

    /// R21-010-tails (holistic cell): live-plant arm. Own fn
    /// so a vacuous plant (contended reuse control) skips
    /// ONLY this cell (the R17-003 rule — loud eprintln,
    /// never a silent pass of the whole test).
    #[cfg(target_arch = "x86_64")]
    fn tail_live_plant_cell() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        {
            let _hold = match steer_hold() {
                Some(hold) => hold,
                None => {
                    eprintln!("TAIL-live: vacuous (no reuse control)");
                    return;
                }
            };
            let mut publisher = spawn_self_grouped_publisher("941", "wait", &[]);
            let pubpid = publisher.id() as libc::pid_t;
            // R23-011: TREE guard at spawn (parse-gap coverage —
            // a read/parse panic before `_sguard` arms must not
            // orphan the stranger's sleep).
            let mut _pguard = PublisherTreeGuard::new(pubpid);
            let mut line = String::new();
            std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
                .read_line(&mut line)
                .expect("pair readable");
            let (stranger, stick) = parse_published_pair(line.trim(), "tail publication");
            let pubtick = proc_starttime(pubpid)
                .expect("publisher stat readable")
                .expect("publisher visible");
            let mut _sguard = FixtureGuard::new_expected(stranger, stick);
            assert!(
                _sguard.tick.is_some(),
                "TAIL-live: stranger birth pinned at sighting"
            );
            // Retire OUR pair explicitly (loud): stranger
            // first (its death releases the publisher's wait
            // tail), then reap the publisher.
            assert!(
                retire_tick_gated_audit_child(stranger, stick),
                "TAIL-live: stranger retire readable"
            );
            assert!(
                await_proc_gone_reaping(stranger, stick, Duration::from_secs(5)),
                "TAIL-live: stranger must drain"
            );
            _sguard.disarm();
            let start = Instant::now();
            let status = loop {
                match publisher.try_wait() {
                    Ok(Some(status)) => break status,
                    Ok(None) => {
                        if start.elapsed() >= Duration::from_secs(5) {
                            panic!("TAIL-live: publisher must exit after its sleep dies");
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(error) => panic!("TAIL-live: publisher wait failed: {error:?}"),
                }
            };
            assert!(status.success(), "TAIL-live: publisher must exit clean");
            _pguard.disarm();
            // Plant a live replacement on the freed number
            // (vacuous under contention — the R17-003 rule).
            let (mut kid, mut plant_guard) = match plant_replacement(pubpid, pubtick) {
                Some(pair) => pair,
                None => {
                    eprintln!("TAIL-live: vacuous (plant contended)");
                    return;
                }
            };
            let retick = proc_starttime(pubpid)
                .expect("replacement readable")
                .expect("replacement live");
            // THE tail (stale tick — the exact call the
            // pair-setup tails make after OUR birth retired).
            let start = Instant::now();
            let _ = retire_tick_gated_audit_child(pubpid, pubtick);
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "TAIL-live: tail must be prompt (never blocking)"
            );
            assert_eq!(
                proc_starttime(pubpid).expect("replacement readable"),
                Some(retick),
                "TAIL-live: replacement murdered?!"
            );
            // Settle (death is async — an instant sample
            // misreads murder as survival): the plant must
            // stay live with an empty pending mask across
            // the FULL window (a murdered plant flips Z in
            // ms; a spared one never receives a signal).
            assert!(settle_spared(pubpid), "TAIL-live: replacement murdered?!");
            assert!(
                matches!(kid.try_wait(), Ok(None)),
                "TAIL-live: replacement status stolen?!"
            );
            // Cleanup (loud): kill+reap the plant.
            let _ = kid.kill();
            let start = Instant::now();
            loop {
                match kid.try_wait() {
                    Ok(Some(_)) => break,
                    Ok(None) => {
                        if start.elapsed() >= Duration::from_secs(5) {
                            panic!("TAIL-live: plant must reap");
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(error) => panic!("TAIL-live: plant wait failed: {error:?}"),
                }
            }
            plant_guard.disarm();
        }
    }

    /// R21-010-tails (holistic cell): zombie-plant arm. Own
