    /// R22-001: the group-emptiness observation must never
    /// reap a replacement child — waitpid(-pgid) after the
    /// pin released steals a sibling zombie's status (our
    /// children include every test thread's children) and a
    /// subsequent signal-0 probe then falsely reports ESRCH.
    /// Leg 1 (before entry): original pair retired (leader
    /// reaped — pin released), replacement steered onto the
    /// freed pgid number, self-grouped, settled zombie
    /// (unreaped — owner handle held) → the observation must
    /// report NON-empty and the owner must retain the status.
    /// RED (old -pgid drain): reaps the plant + reports
    /// empty. GREEN: false + intact status. Tail pattern:
    /// tick re-read → mismatch disarms (number not-ours — a
    /// guard drop must never risk a sibling recycle) →
    /// primary assert → match reaps via the owner handle
    /// (pinned-ours — sound). Duration 945 is unique to
    /// this test. Leg 2 (mid-probe release + join) is the
    /// sibling test below (no steering — always runs).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn group_observation_never_reaps_replacement_children() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        // Leg 1: replacement zombie squatting the discharged
        // pgid number before entry.
        {
            let _hold = match steer_hold() {
                Some(hold) => hold,
                None => {
                    eprintln!("R22001-leg1: vacuous (no reuse control)");
                    return;
                }
            };
            let mut publisher = spawn_self_grouped_publisher("945", "wait", &[]);
            let pubpid = publisher.id() as libc::pid_t;
            // R22-014: guard at birth (the pair read below
            // must not strand the publisher). R23-011: TREE
            // guard — a read/parse panic before `_sguard`
            // can arm over the unknown stranger must not
            // orphan the stranger's sleep.
            let mut _pguard = PublisherTreeGuard::new(pubpid);
            let mut line = String::new();
            std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
                .read_line(&mut line)
                .expect("pair readable");
            let (stranger, stick) = parse_published_pair(line.trim(), "r22001 publication");
            // R22-014: guard the transmitted sleep
            // (expected-tick pin — live, so it takes).
            let mut _sguard = FixtureGuard::new_expected(stranger, stick);
            assert!(
                _sguard.tick.is_some(),
                "R22001-leg1: sleep pin must take (transmitted birth live)"
            );
            let pubtick = proc_starttime(pubpid)
                .expect("publisher stat readable")
                .expect("publisher visible");
            // Retire OUR pair explicitly (leader reaped via
            // its handle — pin RELEASED).
            assert!(
                retire_tick_gated_audit_child(stranger, stick),
                "R22001-leg1: stranger retire readable"
            );
            assert!(
                await_proc_gone_reaping(stranger, stick, Duration::from_secs(5)),
                "R22001-leg1: stranger must drain"
            );
            let start = Instant::now();
            let status = loop {
                match publisher.try_wait() {
                    Ok(Some(status)) => break status,
                    Ok(None) => {
                        if start.elapsed() >= Duration::from_secs(5) {
                            panic!("R22001-leg1: publisher must exit after its sleep dies");
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(error) => panic!("R22001-leg1: publisher wait failed: {error:?}"),
                }
            };
            assert!(status.success(), "R22001-leg1: publisher must exit clean");
            _pguard.disarm();
            _sguard.disarm();
            // Plant a SELF-GROUPED replacement on the freed
            // pgid number (steered retake + S100-vacuity, as
            // plant_replacement — with the group flag).
            let mut kid = match steer_sleep_onto(pubpid, true) {
                Some(kid) => kid,
                None => {
                    eprintln!("R22001-leg1: vacuous (plant contended)");
                    return;
                }
            };
            let mut plant_guard = FixtureGuard::new(pubpid);
            let retick = match proc_starttime(pubpid) {
                Ok(Some(tick)) => tick,
                _ => {
                    let _ = kid.kill();
                    let _ = kid.wait();
                    plant_guard.disarm();
                    eprintln!("R22001-leg1: vacuous (plant unreadable)");
                    return;
                }
            };
            if retick == pubtick {
                let _ = kid.kill();
                let _ = kid.wait();
                plant_guard.disarm();
                eprintln!("R22001-leg1: vacuous (same-tick retake — S100)");
                return;
            }
            assert_eq!(
                proc_pgrp(pubpid),
                Some(pubpid),
                "R22001-leg1: plant must self-group onto the recycled number"
            );
            assert!(
                settle_replacement_zombie(&mut kid, pubpid),
                "R22001-leg1: staging broken (plant never zombified)"
            );
            // THE observation (pin released — the plant is a
            // squatter, unreaped, owner handle held).
            let empty = await_group_empty(pubpid, Duration::from_secs(1));
            // Tail pattern: tick re-read first (mismatch =
            // stolen (reaped) — disarm before asserting, the
            // number is not-ours now).
            if proc_starttime(pubpid) != Ok(Some(retick)) {
                plant_guard.disarm();
            }
            assert!(
                !empty,
                "R22001-leg1: replacement group present — must not certify empty"
            );
            // Owner retains the status (reap proves no steal).
            match kid.try_wait() {
                Ok(Some(status)) => assert!(
                    !status.success(),
                    "R22001-leg1: plant must be our SIGKILLed zombie"
                ),
                other => panic!("R22001-leg1: status stolen?! got {other:?}"),
            }
            plant_guard.disarm();
        }
    }

    /// R22-001 leg 2 (after the last original drain —
    /// mid-probe release + join): live self-grouped leader
    /// (pin held at entry) + joined live plant; the probe
    /// runs threaded while the leader is killed+zombified
    /// (the probe must not steal the leader either — its
    /// status belongs to the handle), reaped by the owner
    /// mid-probe (pin released), and the plant zombified →
    /// no steal anywhere, both owners retain, the probe
    /// reports non-empty. No steering (a join, not a
    /// retake — always runs). RED (old -pgid drain): steals
    /// mid-probe + certifies empty. GREEN: false + intact
    /// statuses. Durations 946/942 are unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn group_observation_never_reaps_joined_mid_probe() {
        use std::time::{Duration, Instant};
        {
            use std::os::unix::process::CommandExt as _;
            let mut leader_cmd = std::process::Command::new("/bin/sleep");
            leader_cmd
                .arg("946")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null());
            // SAFETY: setpgid on self pre-exec, no userspace state.
            unsafe {
                leader_cmd.pre_exec(|| {
                    if libc::setpgid(0, 0) == 0 {
                        Ok(())
                    } else {
                        Err(std::io::Error::last_os_error())
                    }
                });
            }
            let mut leader = leader_cmd.spawn().expect("leader spawns");
            let lpid = leader.id() as libc::pid_t;
            let mut lguard = FixtureGuard::new(lpid);
            let ltick = proc_starttime(lpid)
                .expect("leader stat readable")
                .expect("leader visible");
            assert_eq!(
                proc_pgrp(lpid),
                Some(lpid),
                "R22001-leg2: leader must self-group"
            );
            // The plant joins OUR group pre-exec (setpgid
            // on an exec'd child is refused — the join must
            // happen before the image loads).
            let mut plant_cmd = std::process::Command::new("/bin/sleep");
            plant_cmd
                .arg("942")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null());
            // SAFETY: setpgid-join pre-exec, no userspace state.
            unsafe {
                plant_cmd.pre_exec(move || {
                    if libc::setpgid(0, lpid) == 0 {
                        Ok(())
                    } else {
                        Err(std::io::Error::last_os_error())
                    }
                });
            }
            let mut plant = plant_cmd.spawn().expect("plant spawns");
            let ppid = plant.id() as libc::pid_t;
            let mut pguard = FixtureGuard::new(ppid);
            let ptick = proc_starttime(ppid)
                .expect("plant stat readable")
                .expect("plant visible");
            assert_eq!(proc_pgrp(ppid), Some(lpid), "R22001-leg2: plant grouped");
            // Probe threaded (1 s window — every main action
            // below lands inside with huge margins).
            let probe = std::thread::spawn(move || await_group_empty(lpid, Duration::from_secs(1)));
            std::thread::sleep(Duration::from_millis(50));
            // Kill the leader (zombie, pin STILL held — the
            // probe must not steal it: its status belongs to
            // the handle).
            assert!(
                kill_tick_gated(lpid, ltick),
                "R22001-leg2: leader kill readable"
            );
            // Settle window (the old drain certainly polled —
            // 1 ms polls; a >100 ms scheduling stall is the
            // only miss, and the plant leg below still REDs).
            std::thread::sleep(Duration::from_millis(100));
            // The last original drain (owner reaps — pin
            // released mid-probe).
            let leader_status = leader.try_wait();
            if !matches!(leader_status, Ok(None)) {
                lguard.disarm();
            }
            // Zombify the joined plant (owner holds).
            // Settle accepts Z OR gone: on RED runs the old
            // drain may reap the zombie before this poll sees
            // Z (gone then is RED evidence, not broken
            // staging); a plant still LIVE past the bound is
            // broken staging (the kill failed).
            let _ = plant.kill();
            let end = Instant::now() + Duration::from_secs(5);
            loop {
                match proc_state(ppid) {
                    Some('Z') | None => break,
                    Some(_) => {}
                }
                assert!(
                    Instant::now() < end,
                    "R22001-leg2: staging broken (plant never zombified)"
                );
                std::thread::sleep(Duration::from_millis(1));
            }
            let empty = probe.join().expect("probe bounded");
            if proc_starttime(ppid) != Ok(Some(ptick)) || proc_pgrp(ppid) != Some(lpid) {
                // Occupant changed (stolen + recycled, or
                // re-grouped) — disarm before asserting.
                pguard.disarm();
            }
            assert!(
                !empty,
                "R22001-leg2: replacement zombie present — must not certify empty"
            );
            match leader_status {
                Ok(Some(status)) => assert!(
                    !status.success(),
                    "R22001-leg2: leader must be our SIGKILLed zombie (status belongs to the handle)"
                ),
                other => panic!("R22001-leg2: leader status stolen?! got {other:?}"),
            }
            match plant.try_wait() {
                Ok(Some(status)) => assert!(
                    !status.success(),
                    "R22001-leg2: plant must be our SIGKILLed zombie"
                ),
                other => panic!("R22001-leg2: plant status stolen?! got {other:?}"),
            }
            pguard.disarm();
        }
    }

    /// R23-011 leg (audit, in-process): mirror of the
    /// toolchain leg — a garbage-pair publisher panics the
    /// pair parse INSIDE a caught unwind with the TREE guard
    /// armed; the drop must retire BOTH the publisher and
    /// the unknown stranger (no expected-identity guard CAN
    /// arm — the birth never parsed). Bad variant: the same
    /// shape with a BARE publisher guard strands the
    /// stranger's sleep (proven by the owned duration scan,
    /// then swept loud). Dur 852 is unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn r23011_tree_guard_retires_unknown_stranger_on_parse_panic() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        let anchor = boot_ticks_now().expect("tick reads");
        // GOOD arm: tree guard.
        let mut publisher = spawn_self_grouped_publisher(
            "852",
            "wait",
            &[("SCOPEBASE_PUBLISHER_GARBAGE_PAIR", "1")],
        );
        let pubpid = publisher.id() as libc::pid_t;
        let stdout = publisher.stdout.take().expect("publisher stdout");
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut _tguard = PublisherTreeGuard::new(pubpid);
            let mut line = String::new();
            std::io::BufReader::new(stdout)
                .read_line(&mut line)
                .expect("pair readable");
            let (_stranger, _stick) = parse_published_pair(line.trim(), "garbage publication");
        }));
        assert!(
            outcome.is_err(),
            "R23011-parse: garbage pair must panic the parse"
        );
        // Publisher: our child — reap whatever the drop left
        // (kill-only or already-reaped both converge) and
        // prove the number gone.
        let _ = publisher.wait();
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            match proc_starttime(pubpid) {
                Ok(None) => break,
                Ok(Some(_)) => {}
                Err(error) => panic!("R23011-parse: publisher drain unreadable: {error}"),
            }
            assert!(
                Instant::now() < end,
                "R23011-parse: tree guard failed to retire the publisher"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        // Stranger: unknown number — scan-absence after the
        // settle is the discharge proof (dur unique + owned).
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            if r22006_scan_owned_sleep_with_dur("852", anchor).is_empty() {
                break;
            }
            assert!(
                Instant::now() < end,
                "R23011-parse: tree guard failed to retire the unknown stranger"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        // BAD arm: bare publisher guard — the stranger MUST
        // strand (orphaned to init when the drop kills the
        // publisher alone), or the leg is vacuous. Swept loud.
        let mut publisher = spawn_self_grouped_publisher(
            "852",
            "wait",
            &[("SCOPEBASE_PUBLISHER_GARBAGE_PAIR", "1")],
        );
        let pubpid = publisher.id() as libc::pid_t;
        let stdout = publisher.stdout.take().expect("publisher stdout");
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut _tguard = FixtureGuard::new(pubpid);
            let mut line = String::new();
            std::io::BufReader::new(stdout)
                .read_line(&mut line)
                .expect("pair readable");
            let (_stranger, _stick) = parse_published_pair(line.trim(), "garbage publication");
        }));
        assert!(
            outcome.is_err(),
            "R23011-parse-bad: garbage pair must panic the parse"
        );
        let _ = publisher.wait();
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            match proc_starttime(pubpid) {
                Ok(None) => break,
                Ok(Some(_)) => {}
                Err(error) => panic!("R23011-parse-bad: publisher drain unreadable: {error}"),
            }
            assert!(
                Instant::now() < end,
                "R23011-parse-bad: bare guard failed to retire the publisher"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        // THE bad assertion: the stranger strands.
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            if !r22006_scan_owned_sleep_with_dur("852", anchor).is_empty() {
                break;
            }
            assert!(
                Instant::now() < end,
                "R23011-parse-bad: bad variant must strand the stranger (else the leg is vacuous)"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(
            r22006_fallback_sweep_sleep("852", anchor),
            1,
            "R23011-parse-bad: sweep must drain exactly the stranded stranger"
        );
    }

    /// R23-011 site-4 read leg (audit): mirror of the
    /// toolchain leg — the tree guard drops UNDER a held
    /// outage (real fd exhaustion via confine+fill): the
    /// liveness check fails, the tree arm is SKIPPED loud
    /// (no blind snapshot-kill of an unverifiable subtree),
    /// the inner unpinned arm still retires the publisher
    /// via the fd-less waitpid probe, and the unknown
    /// stranger strands (the wrapper sweeps it loud).
    /// Fresh-image probe (the outage is process-global); the
    /// probe panics by design with custody on stderr.
    /// Unguarded bad control (must strand the PAIR —
    /// publisher included) + guarded shape (loud line +
    /// publisher gone + stranger stranded). Duration 845 is
    /// unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn r23011_tree_guard_skips_tree_loud_under_outage() {
        if std::env::var("SCOPEBASE_R23011_TREE_OUTAGE_AUDIT").is_ok() {
            r23011_tree_guard_outage_probe();
            return;
        }
        // R23-008: ownership-window anchor — wrapper entry
        // (before either probe stages anything).
        let anchor = boot_ticks_now().expect("custody anchor needs the boot clock");
        for no_arm in [true, false] {
            let exe = std::env::current_exe().expect("own test binary");
            let mut cmd = std::process::Command::new(exe);
            cmd.arg("--exact")
                .arg("fixture::linux::audit::tests::r23011_tree_guard_skips_tree_loud_under_outage")
                .arg("--nocapture")
                .env("SCOPEBASE_R23011_TREE_OUTAGE_AUDIT", "1")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            if no_arm {
                cmd.env("SCOPEBASE_R23011_NO_ARM", "1");
            }
            let out = cmd.output().expect("probe runs");
            let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
            // The probe panics by design (the parse panic
            // unwinds through the guard); custody rides
            // stderr (unbuffered — survives the panic).
            assert!(
                !out.status.success(),
                "probe must panic on the parse\n{stderr}"
            );
            assert!(
                stderr.contains("garbage publication"),
                "probe must cite the parse panic\n{stderr}"
            );
            let (pubpid, pubtick): (libc::pid_t, u64) = stderr
                .lines()
                .find_map(|line| {
                    let rest = line.strip_prefix("R23011-TREE-PAIR ")?;
                    let mut words = rest.split_whitespace();
                    Some((
                        words.next()?.parse().ok()?,
                        words.next()?.parse().ok()?,
                    ))
                })
                .expect("probe must print custody");
            if no_arm {
                // Bad control: the SAME publisher birth must
                // still be live (else vacuous) and the
                // stranger stranded — then sweep loud (the
                // adopted publisher zombie rides the suite
                // process like the site-2 shape).
                assert_eq!(
                    proc_starttime(pubpid),
                    Ok(Some(pubtick)),
                    "bad control must strand the publisher (vacuous otherwise)"
                );
                assert!(
                    !r22006_scan_owned_sleep_with_dur("845", anchor).is_empty(),
                    "bad control must strand the stranger"
                );
                assert!(
                    !stderr.contains("publisher-tree"),
                    "unguarded probe must not emit the tree line"
                );
                let _ = kill_tick_gated(pubpid, pubtick);
                assert_eq!(
                    r22006_fallback_sweep_sleep("845", anchor),
                    1,
                    "wrapper must sweep the stranded sleep"
                );
                eprintln!("R23011: bad control stranded + swept as designed");
            } else {
                // Guarded: the skip must go LOUD (the arm is
                // reachable + wired, not dead code), the
                // publisher must be gone (inner fd-less arm),
                // and the unknown stranger must strand (no
                // blind kill) for the wrapper to sweep.
                assert!(
                    stderr.contains("publisher-tree")
                        && stderr.contains("publisher-unverifiable"),
                    "guarded probe must go loud on the skipped tree\n{stderr}"
                );
                // Arm precision: the liveness check (not the
                // children read) must be what failed.
                assert!(
                    !stderr.contains("children-unreadable"),
                    "guarded probe must fail the liveness check, not the children read\n{stderr}"
                );
                let end =
                    std::time::Instant::now() + std::time::Duration::from_secs(5);
                loop {
                    if proc_starttime(pubpid) != Ok(Some(pubtick)) {
                        break;
                    }
                    assert!(
                        std::time::Instant::now() < end,
                        "guarded probe must retire the publisher"
                    );
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                assert!(
                    !r22006_scan_owned_sleep_with_dur("845", anchor).is_empty(),
                    "guarded probe must strand the unknown stranger"
                );
                assert_eq!(
                    r22006_fallback_sweep_sleep("845", anchor),
                    1,
                    "wrapper must sweep the stranded sleep"
                );
            }
        }
    }

    /// R23-011 site-4 read probe (fresh image):
    /// garbage-pair publisher + the tree guard dropped UNDER
    /// a held outage. Read pre-hold (staging — the pipe fd
    /// must close before exhaustion: a reader dropped during
    /// unwind would free a slot ahead of the guard and the
    /// liveness check would wrongly succeed); confine+fill;
    /// guard (unless bad control — declared after the fill
    /// so unwind reaches it first, fds still exhausted);
    /// the parse then panics BY DESIGN — unwind takes the
    /// loud skip + inner fd-less publisher retire, and the
    /// probe dies nonzero with custody on stderr (the
    /// wrapper judges + sweeps).
    #[cfg(target_arch = "x86_64")]
    fn r23011_tree_guard_outage_probe() {
        use std::io::BufRead as _;
        let no_arm = std::env::var("SCOPEBASE_R23011_NO_ARM").is_ok();
        let mut publisher = spawn_self_grouped_publisher(
            "845",
            "wait",
            &[("SCOPEBASE_PUBLISHER_GARBAGE_PAIR", "1")],
        );
        let pubpid = publisher.id() as libc::pid_t;
        let pubtick = proc_starttime(pubpid)
            .expect("staging broken (publisher stat)")
            .expect("staging broken (publisher visible)");
        let mut line = String::new();
        std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
            .read_line(&mut line)
            .expect("pair readable");
        eprintln!("R23011-TREE-PAIR {pubpid} {pubtick}");
        // Real outage (confine + fill — the established
        // audit shape).
        let _confine = confine_fd_table_for_exhaustion();
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "exhaustion must consume fds");
        // Guard UNDER the outage (drops with fds exhausted —
        // this probe covers the loud skip).
        let mut _tguard = (!no_arm).then(|| PublisherTreeGuard::new(pubpid));
        // Anti-vacuity: the outage bites exactly here.
        assert!(
            proc_starttime(pubpid).is_err(),
            "staging broken (stat readable under hold?)"
        );
        // THE panic (by design — unwinds through the guard;
        // the wrapper judges the stderr).
        let (_stranger, _stick) = parse_published_pair(line.trim(), "garbage publication");
    }

    /// R22-002 working paths (no steering — always runs):
    /// the hung branch retires a live publisher group and
    /// the exited branch retires a zombie-leader group with
    /// a stranded sleeper — both while the pin holds (never
    /// an unpinned killpg). Hung cell: a live unparsed
    /// publisher (real bin — production-identical) retires
    /// promptly with the group ESRCH-empty and a SIGKILLed
    /// status. Exited cell: a sh-leader (self-grouped, `sleep
    /// & wait`) killed to an unreaped zombie (pin held)
    /// with its live sleep orphaned to init (NOT ours —
    /// exactly like production) → the branch records
    /// stranded, killpgs pinned, settles, reaps, and proves
    /// ESRCH-empty. RED (neuter — the fns postdate the bug,
    /// so pre-fix code does not compile this test; skipping
    /// the killpg strands the sleeper and the settle times
    /// out). GREEN: prompt retires, recorded stranded,
    /// SIGKILLed statuses, ESRCH proofs. Duration 963 (hung
    /// publisher) and 865 (stranded sleep) are unique to
    /// this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn hung_and_exited_branches_retire_while_pinned() {
        use std::time::{Duration, Instant};
        // Hung cell: live publisher, real bin.
        {
            let mut publisher = spawn_self_grouped_publisher("963", "wait", &[]);
            let pubpid = publisher.id() as libc::pid_t;
            let pubtick = proc_starttime(pubpid)
                .expect("publisher stat readable")
                .expect("publisher visible");
            // R23-022: the tree guard covers the staging
            // below (a staging panic retires the pair —
            // never strands; disarmed once the retire
            // below reaps).
            let mut _tguard = PublisherTreeGuard::new(pubpid);
            // R23-022: await EXACTLY ONE live sleep child —
            // the publisher births its sleeper async, and
            // striking pre-spawn retires an empty group
            // (vacuous — a no-strike mutant passes). Pre-exec
            // (publisher argv, not sleep yet) and transient
            // counts keep polling; a second child or a dead
            // sleeper is staging-broken (loud — the
            // publisher births exactly one sleeper and
            // nothing targets it pre-strike).
            let (spid, stick) = {
                let end = Instant::now() + Duration::from_secs(5);
                loop {
                    let kids = proc_children(pubpid).unwrap_or_default();
                    if kids.len() > 1 {
                        panic!(
                            "R22002-hung: staging broken (publisher birthed {} children, want 1)",
                            kids.len()
                        );
                    }
                    let mut sleeps = Vec::new();
                    for kid in &kids {
                        let cmdline = match std::fs::read(format!("/proc/{kid}/cmdline")) {
                            Ok(cmdline) => cmdline,
                            Err(_) => continue,
                        };
                        if !r22006_cmdline_matches_sleep_dur(&cmdline, "963") {
                            continue;
                        }
                        let tick = match proc_starttime(*kid) {
                            Ok(Some(tick)) => tick,
                            _ => continue,
                        };
                        let cmdline2 = match std::fs::read(format!("/proc/{kid}/cmdline")) {
                            Ok(cmdline) => cmdline,
                            Err(_) => continue,
                        };
                        if !r22006_cmdline_matches_sleep_dur(&cmdline2, "963") {
                            continue;
                        }
                        if proc_state(*kid) == Some('Z') {
                            panic!(
                                "R22002-hung: staging broken (sleeper {kid} dead pre-strike — nothing targets it?)"
                            );
                        }
                        sleeps.push((*kid, tick));
                    }
                    if sleeps.len() == 1 {
                        break sleeps[0];
                    }
                    assert!(
                        Instant::now() < end,
                        "R22002-hung: staging broken (sleep child never appeared)"
                    );
                    std::thread::sleep(Duration::from_millis(1));
                }
            };
            let start = Instant::now();
            let status = retire_hung_publisher_group(&mut publisher, pubpid, pubtick);
            _tguard.disarm();
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "R22002-hung: retire must be prompt"
            );
            assert!(!status.success(), "R22002-hung: leader must be SIGKILLed");
            assert!(
                await_group_empty(pubpid, Duration::from_secs(1)),
                "R22002-hung: group must be ESRCH-empty"
            );
            // R23-022: the strike retired THE proven drain
            // (birth-bound — a surviving same-number stranger
            // fails here even if the group reads empty).
            assert!(
                await_proc_gone_reaping(spid, stick, Duration::from_secs(5)),
                "R22002-hung: proven sleeper {spid} must drain (strike missed?)"
            );
        }
        // Exited cell: zombie sh-leader (pin held) + live
        // sleep orphaned to init (stranded, not ours).
        {
            use std::os::unix::process::CommandExt as _;
            let mut leader_cmd = std::process::Command::new("/bin/sh");
            leader_cmd
                .arg("-c")
                .arg("sleep 865 & wait")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null());
            // SAFETY: setpgid on self pre-exec, no userspace state.
            unsafe {
                leader_cmd.pre_exec(|| {
                    if libc::setpgid(0, 0) == 0 {
                        Ok(())
                    } else {
                        Err(std::io::Error::last_os_error())
                    }
                });
            }
            let mut leader = leader_cmd.spawn().expect("leader spawns");
            let lpid = leader.id() as libc::pid_t;
            let mut lguard = FixtureGuard::new(lpid);
            let ltick = proc_starttime(lpid)
                .expect("leader stat readable")
                .expect("leader visible");
            assert_eq!(
                proc_pgrp(lpid),
                Some(lpid),
                "R22002-exited: leader must self-group"
            );
            // Discover the sleep (the non-leader member —
            // only two members ever exist here).
            let (spid, stick) = {
                let end = Instant::now() + Duration::from_secs(5);
                loop {
                    let others: Vec<(libc::pid_t, u64)> = enumerate_group_members(lpid)
                        .iter()
                        .filter(|member| member.pid != lpid)
                        .filter_map(|member| member.birth.map(|(_, tick)| (member.pid, tick)))
                        .collect();
                    if others.len() == 1 {
                        break others[0];
                    }
                    assert!(
                        Instant::now() < end,
                        "R22002-exited: staging broken (sleep never appeared)"
                    );
                    std::thread::sleep(Duration::from_millis(1));
                }
            };
            // Kill the leader to a zombie (pin HELD —
            // unreaped); the sleep orphans to init (live,
            // not ours — ECHILD for us, exactly like
            // production).
            assert!(
                kill_tick_gated(lpid, ltick),
                "R22002-exited: leader kill readable"
            );
            let end = Instant::now() + Duration::from_secs(5);
            loop {
                if proc_state(lpid) == Some('Z') {
                    break;
                }
                assert!(
                    Instant::now() < end,
                    "R22002-exited: staging broken (leader never zombified)"
                );
                std::thread::sleep(Duration::from_millis(1));
            }
            let start = Instant::now();
            let (status, stranded, post_empty) =
                retire_exited_publisher_group(&mut leader, lpid, ltick);
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "R22002-exited: retire must be prompt"
            );
            assert!(stranded, "R22002-exited: stranding must be recorded");
            assert!(!status.success(), "R22002-exited: leader must be SIGKILLed");
            assert!(post_empty, "R22002-exited: group must prove ESRCH-empty");
            assert!(
                await_proc_gone_reaping(spid, stick, Duration::from_secs(5)),
                "R22002-exited: stranded sleep must drain"
            );
            lguard.disarm();
        }
    }

    /// R22-002 refusal paths (steered squatters — vacuous
    /// under contention): both branch fns re-pin (birth
    /// re-read) before any killpg — a discharged number
    /// (leader reaped by the test, live self-grouped
    /// squatter steered onto it) with a STALE tick must
    /// panic WITHOUT killing (reaped/gone → no killpg) and
    /// the squatter must survive unsignaled (settled-spared
    /// across the full window — never a signal). RED
    /// (neuter — same signature note as the working test;
    /// skipping the re-pin murders the squatter). GREEN:
    /// loud refusal + survival, both branches. Duration 963
    /// (publisher staging) is unique to this test (the
    /// squatter is the steered sleep-31 standin).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn hung_and_exited_branches_refuse_discharged_numbers() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        // Stage per cell: spawn, retire OUR pair explicitly
        // (pin RELEASED), steer a live self-grouped squatter
        // onto the freed number. Returns the stale handle +
        // freed number + original tick + squatter parts, or
        // None when vacuous (caller returns, cell skipped).
        macro_rules! stage_discharged {
            ($cell:expr) => {{
                let mut publisher = spawn_self_grouped_publisher("964", "wait", &[]);
                let pubpid = publisher.id() as libc::pid_t;
                let mut line = String::new();
                std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
                    .read_line(&mut line)
                    .expect("pair readable");
                let (stranger, stick) = parse_published_pair(line.trim(), "r22002 publication");
                let pubtick = proc_starttime(pubpid)
                    .expect("publisher stat readable")
                    .expect("publisher visible");
                assert!(
                    retire_tick_gated_audit_child(stranger, stick),
                    "R22002-{}: stranger retire readable",
                    $cell
                );
                assert!(
                    await_proc_gone_reaping(stranger, stick, Duration::from_secs(5)),
                    "R22002-{}: stranger must drain",
                    $cell
                );
                let start = Instant::now();
                loop {
                    match publisher.try_wait() {
                        Ok(Some(_)) => break,
                        Ok(None) => {
                            if start.elapsed() >= Duration::from_secs(5) {
                                panic!("R22002-{}: publisher must exit", $cell);
                            }
                            std::thread::sleep(Duration::from_millis(1));
                        }
                        Err(error) => panic!("R22002-{}: wait failed: {error:?}", $cell),
                    }
                }
                let mut squatter = match steer_sleep_onto(pubpid, true) {
                    Some(kid) => kid,
                    None => {
                        eprintln!("R22002-{}: vacuous (squatter contended)", $cell);
                        return;
                    }
                };
                let mut squatter_guard = FixtureGuard::new(pubpid);
                let squat_tick = match proc_starttime(pubpid) {
                    Ok(Some(tick)) => tick,
                    _ => {
                        let _ = squatter.kill();
                        let _ = squatter.wait();
                        squatter_guard.disarm();
                        eprintln!("R22002-{}: vacuous (squatter unreadable)", $cell);
                        return;
                    }
                };
                if squat_tick == pubtick {
                    let _ = squatter.kill();
                    let _ = squatter.wait();
                    squatter_guard.disarm();
                    eprintln!("R22002-{}: vacuous (same-tick retake — S100)", $cell);
                    return;
                }
                assert_eq!(
                    proc_pgrp(pubpid),
                    Some(pubpid),
                    "R22002-{}: squatter must self-group onto the recycled number",
                    $cell
                );
                (
                    publisher,
                    pubpid,
                    pubtick,
                    squatter,
                    squatter_guard,
                    squat_tick,
                )
            }};
        }
        let _hold = match steer_hold() {
            Some(hold) => hold,
            None => {
                eprintln!("R22002-refuse: vacuous (no reuse control)");
                return;
            }
        };
        // Hung cell: stale handle + stale tick on a live
        // squatter's number → refusal (no killpg).
        {
            let (mut publisher, pubpid, pubtick, mut squatter, mut squatter_guard, squat_tick) =
                stage_discharged!("hung");
            let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                retire_hung_publisher_group(&mut publisher, pubpid, pubtick);
            }));
            let error = match failed {
                Ok(_) => panic!("R22002-hung: must refuse loud"),
                Err(error) => error,
            };
            let message = error.downcast_ref::<String>().cloned().unwrap_or_default();
            assert!(
                message.contains("pin lost"),
                "R22002-hung: refusal must name the lost pin, got {message:?}"
            );
            assert!(settle_spared(pubpid), "R22002-hung: squatter murdered?!");
            assert_eq!(
                proc_starttime(pubpid).expect("squatter readable"),
                Some(squat_tick),
                "R22002-hung: squatter birth must persist"
            );
            let _ = squatter.kill();
            let start = Instant::now();
            loop {
                match squatter.try_wait() {
                    Ok(Some(_)) => break,
                    Ok(None) => {
                        if start.elapsed() >= Duration::from_secs(5) {
                            panic!("R22002-hung: squatter must reap");
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(error) => panic!("R22002-hung: squatter wait failed: {error:?}"),
                }
            }
            squatter_guard.disarm();
        }
        // Exited cell: same staging, the exited branch.
        {
            let (mut publisher, pubpid, pubtick, mut squatter, mut squatter_guard, squat_tick) =
                stage_discharged!("exited");
            let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                retire_exited_publisher_group(&mut publisher, pubpid, pubtick);
            }));
            let error = match failed {
                Ok(_) => panic!("R22002-exited: must refuse loud"),
                Err(error) => error,
            };
            let message = error.downcast_ref::<String>().cloned().unwrap_or_default();
            assert!(
                message.contains("pin lost"),
                "R22002-exited: refusal must name the lost pin, got {message:?}"
            );
            assert!(settle_spared(pubpid), "R22002-exited: squatter murdered?!");
            assert_eq!(
                proc_starttime(pubpid).expect("squatter readable"),
                Some(squat_tick),
                "R22002-exited: squatter birth must persist"
            );
            let _ = squatter.kill();
            let start = Instant::now();
            loop {
                match squatter.try_wait() {
                    Ok(Some(_)) => break,
                    Ok(None) => {
                        if start.elapsed() >= Duration::from_secs(5) {
                            panic!("R22002-exited: squatter must reap");
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(error) => panic!("R22002-exited: squatter wait failed: {error:?}"),
                }
            }
            squatter_guard.disarm();
        }
    }

    /// R22-003(c) always-runs (no steering): the gated
    /// faulted-pair cleanup kills PROVEN pairs and skips
    /// ambiguous ones. Working leg: a real middleman (sh
    /// with a sleep child — ours) retires fully (both
    /// killed, m1 reaped — GREEN pre-fix too (the old blind
    /// kills were correct here): non-vacuity). Forged leg:
    /// a live sleeper driven with its OWN tick forged as
    /// the middleman birth (deterministic S100 simulation —
    /// tick-match + childless + not-ours, exactly the
    /// fn's view of a same-tick squatter; no jiffy racing)
    /// → skipped loud, sleeper survives unsignaled.
    /// Zombie leg: a pinned-ours zombie driven with its own
    /// tick (the ambiguous case — ours-zombie vs
    /// squatter-zombie indistinguishable) → skip (no kill,
    /// no reap — leak-vs-steal ⟹ leak), owner retains.
    /// RED (neuter: blind kills + unconditional reap —
    /// murder + steal). Durations 971 (middleman's sleep),
    /// 972 (forged sleeper), 973 (ambiguous zombie) are
    /// unique to this test.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn faulted_pair_cleanup_kills_proven_skips_ambiguous() {
        use std::time::{Duration, Instant};
        // Working leg: real middleman + grandchild (ours).
        {
            let m1 = std::process::Command::new("/bin/sh")
                .arg("-c")
                .arg("sleep 971 & wait")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("middleman spawns");
            let fm1 = m1.id() as libc::pid_t;
            let mut g1 = FixtureGuard::new(fm1);
            let ft1 = proc_starttime(fm1)
                .expect("middleman stat readable")
                .expect("middleman visible");
            // Discover the grandchild (m1's only child).
            let (fm2, ft2) = {
                let end = Instant::now() + Duration::from_secs(5);
                loop {
                    let kids = proc_children(fm1).unwrap_or_default();
                    if kids.len() == 1 {
                        let tick = proc_starttime(kids[0])
                            .expect("grandchild stat readable")
                            .expect("grandchild visible");
                        break (kids[0], tick);
                    }
                    assert!(
                        Instant::now() < end,
                        "R22003c-working: staging broken (grandchild never appeared)"
                    );
                    std::thread::sleep(Duration::from_millis(1));
                }
            };
            let mut g2 = FixtureGuard::new(fm2);
            let start = Instant::now();
            retire_faulted_pair_cleanup(fm1, ft1, fm2, ft2);
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "R22003c-working: cleanup must be prompt"
            );
            assert!(
                await_proc_gone_reaping(fm1, ft1, Duration::from_secs(1)),
                "R22003c-working: middleman must drain"
            );
            assert!(
                await_proc_gone_reaping(fm2, ft2, Duration::from_secs(5)),
                "R22003c-working: grandchild must drain"
            );
            // m1 reaped via raw waitpid (handle stale);
            // drop without waiting.
            drop(m1);
            g1.disarm();
            g2.disarm();
        }
        // Forged leg: live sleeper + its own tick forged as
        // the middleman birth (S100 simulation).
        {
            let mut sleeper = std::process::Command::new("/bin/sleep")
                .arg("972")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("sleeper spawns");
            let spid = sleeper.id() as libc::pid_t;
            let mut guard = FixtureGuard::new(spid);
            let stick = proc_starttime(spid)
                .expect("sleeper stat readable")
                .expect("sleeper visible");
            retire_faulted_pair_cleanup(spid, stick, spid, stick);
            assert!(settle_spared(spid), "R22003c-forged: sleeper murdered?!");
            assert_eq!(
                proc_starttime(spid).expect("sleeper readable"),
                Some(stick),
                "R22003c-forged: sleeper birth must persist"
            );
            let _ = sleeper.kill();
            let _ = sleeper.wait();
            guard.disarm();
        }
        // Zombie leg: pinned-ours zombie + its own tick
        // (ambiguous — skip, owner retains).
        {
            let mut zombie = std::process::Command::new("/bin/sleep")
                .arg("973")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .expect("zombie spawns");
            let zpid = zombie.id() as libc::pid_t;
            let mut guard = FixtureGuard::new(zpid);
            let ztick = proc_starttime(zpid)
                .expect("zombie stat readable")
                .expect("zombie visible");
            let _ = zombie.kill();
            let end = Instant::now() + Duration::from_secs(5);
            loop {
                if proc_state(zpid) == Some('Z') {
                    break;
                }
                assert!(
                    Instant::now() < end,
                    "R22003c-zombie: staging broken (never zombified)"
                );
                std::thread::sleep(Duration::from_millis(1));
            }
            retire_faulted_pair_cleanup(zpid, ztick, zpid, ztick);
            // Still a zombie (not reaped — leak accepted),
            // status with the owner (not stolen).
            assert_eq!(
                proc_state(zpid),
                Some('Z'),
                "R22003c-zombie: must stay unreaped (leak-vs-steal)"
            );
            match zombie.try_wait() {
                Ok(Some(status)) => assert!(
                    !status.success(),
                    "R22003c-zombie: must be our SIGKILLed zombie"
                ),
                other => panic!("R22003c-zombie: status stolen?! got {other:?}"),
            }
            guard.disarm();
        }
    }

    /// R22-003(c) steered (vacuous under contention):
    /// retired-then-recycled numbers with DIFFERENT ticks
    /// (the easy case — tick-mismatch) skip loud and both
    /// live squatters survive unsignaled. RED (neuter: blind
    /// kills murder both). Durations 974/975 (staging
    /// births) are unique to this test (squatters are
    /// steered sleep-31 standins).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn faulted_pair_cleanup_skips_recycled_numbers() {
        use std::time::Duration;
        let _hold = match steer_hold() {
            Some(hold) => hold,
            None => {
                eprintln!("R22003c: vacuous (no reuse control)");
                return;
            }
        };
        macro_rules! stage_squatter {
            ($leg:expr, $secs:expr) => {{
                let mut birth = std::process::Command::new("/bin/sleep")
                    .arg($secs)
                    .stdin(std::process::Stdio::null())
                    .stdout(std::process::Stdio::null())
                    .stderr(std::process::Stdio::null())
                    .spawn()
                    .expect("birth spawns");
                let pid = birth.id() as libc::pid_t;
                // R22-014: guard at birth (the tick read
                // below must not strand the birth).
                let mut _bguard = FixtureGuard::new(pid);
                let tick = proc_starttime(pid)
                    .expect("birth stat readable")
                    .expect("birth visible");
                let _ = birth.kill();
                let start = std::time::Instant::now();
                loop {
                    match birth.try_wait() {
                        Ok(Some(_)) => {
                            _bguard.disarm();
                            break;
                        }
                        Ok(None) => {
                            if start.elapsed() >= Duration::from_secs(5) {
                                panic!("R22003c-{}: birth must reap", $leg);
                            }
                            std::thread::sleep(Duration::from_millis(1));
                        }
                        Err(error) => panic!("R22003c-{}: wait failed: {error:?}", $leg),
                    }
                }
                let mut squatter = match steer_sleep_onto(pid, false) {
                    Some(kid) => kid,
                    None => {
                        eprintln!("R22003c-{}: vacuous (squatter contended)", $leg);
                        return;
                    }
                };
                let mut guard = FixtureGuard::new(pid);
                let squat_tick = match proc_starttime(pid) {
                    Ok(Some(tick)) => tick,
                    _ => {
                        let _ = squatter.kill();
                        let _ = squatter.wait();
                        guard.disarm();
                        eprintln!("R22003c-{}: vacuous (squatter unreadable)", $leg);
                        return;
                    }
                };
                if squat_tick == tick {
                    let _ = squatter.kill();
                    let _ = squatter.wait();
                    guard.disarm();
                    eprintln!("R22003c-{}: vacuous (same-tick retake — S100)", $leg);
                    return;
                }
                (pid, tick, squatter, guard, squat_tick)
            }};
        }
        let (p1, t1, mut s1, mut g1, st1) = stage_squatter!("fm1", "974");
        let (p2, t2, mut s2, mut g2, st2) = stage_squatter!("fm2", "975");
        retire_faulted_pair_cleanup(p1, t1, p2, t2);
        assert!(settle_spared(p1), "R22003c-fm1: squatter murdered?!");
        assert!(settle_spared(p2), "R22003c-fm2: squatter murdered?!");
        assert_eq!(
            proc_starttime(p1).expect("squatter readable"),
            Some(st1),
            "R22003c-fm1: squatter birth must persist"
        );
        assert_eq!(
            proc_starttime(p2).expect("squatter readable"),
            Some(st2),
            "R22003c-fm2: squatter birth must persist"
        );
        let _ = s1.kill();
        let _ = s1.wait();
        let _ = s2.kill();
        let _ = s2.wait();
        g1.disarm();
        g2.disarm();
    }

    /// R19-014: sensitivity lock — the shared verdict must
    /// FAIL on a live pair (missing retirement): the
    /// assistance is reap-only (never kills), so survivors
    /// read Some. In-process (no adoption involved); short
    /// budget (a live-forever pair flips never — any budget
    /// fails; 200ms keeps it fast). Cleanup rides the
    /// guards (never disarmed here). Duration 77 is unique
    /// to this test (both harnesses).
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn stranger_staging_verdict_fails_live_pair() {
        use std::io::BufRead as _;
        use std::time::Duration;
        #[allow(clippy::zombie_processes)]
        let mut publisher = std::process::Command::new(pair_publisher_bin())
            .arg("77")
            .arg("wait")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("publisher spawns");
        let mut line = String::new();
        std::io::BufReader::new(publisher.stdout.take().expect("publisher stdout"))
            .read_line(&mut line)
            .expect("stranger pid readable");
        let (stranger, stick) = parse_published_pair(line.trim(), "stranger publication");
        let pubpid = publisher.id() as libc::pid_t;
        let pubtick = proc_starttime(pubpid)
            .expect("publisher stat readable")
            .expect("publisher visible");
        // Own teardown (the verdict below must NOT retire —
        // the drops here do).
        let _stranger_guard = FixtureGuard::new_expected(stranger, stick);
        let _publisher_guard = FixtureGuard::new(pubpid);
        let failed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            stranger_staging_verdict(stranger, stick, pubpid, pubtick, Duration::from_millis(200));
        }));
        assert!(
            failed.is_err(),
            "verdict must fail a live pair (missing retirement)"
        );
    }

    /// R17-007: probe body (fresh image,
    /// SCOPEBASE_R17007_NONCHILD) — fail the constructor reads
    /// through their budget (EMFILE), succeed the explicit
    /// birth read after restore, then drop: the recovered tick
    /// must reach the guard (late-pin) so the drop retires the
    /// known grandchild. RED (constructor-pin assert): the
    /// assert panics, unwind drops unpinned, ECHILDs past the
    /// live grandchild. Duration 42 is unique to this test.
    #[cfg(target_arch = "x86_64")]
    fn nonchild_pin_recovery_probe() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        // R19003-FLAKE01: confine the table before any
        // exhaustion below (fresh image — the limit dies
        // with the probe).
        let _confined = confine_fd_table_for_exhaustion();
        let mut parent = std::process::Command::new(pair_publisher_bin())
            .arg("42")
            .arg("wait")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("publisher spawns");
        let mut line = String::new();
        std::io::BufReader::new(parent.stdout.take().expect("publisher stdout"))
            .read_line(&mut line)
            .expect("grandchild pid readable");
        // R19-001: transmitted pair (parsed pre-exhaustion —
        // pipe reads need no new fd — so recovery never
        // depends on a post-restore first-read, which would
        // self-authenticate a gap replacement).
        let (grand, tick) = parse_published_pair(line.trim(), "grandchild publication");
        // Fail the constructor reads: exhaust through
        // construction (the retry budget expires to None).
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "exhaustion must consume fds");
        let mut pinned = FixtureGuard::new(grand);
        assert!(
            pinned.tick.is_none(),
            "construction must fail under EMFILE (stage broken otherwise)"
        );
        drop(held);
        // R17-007: pin-before-panic — the constructor
        // exhausted its budget (None); the transmitted tick
        // reaches the guard HERE, before every fallible
        // check below (R18-005: a panic anywhere below
        // unwinds through a PINNED guard that retires the
        // known grandchild).
        if pinned.tick.is_none() {
            pinned.pin(tick);
            eprintln!("R17007 construction pin missed; late-pinned transmitted tick");
        }
        // Post-restore verification (post-pin, so
        // unwind-safe): the table works again and still
        // observes the transmitted birth.
        assert_eq!(
            proc_starttime(grand),
            Ok(Some(tick)),
            "restored table must re-observe the transmitted birth"
        );
        // Sanity: live, and not our child.
        assert!(
            matches!(proc_state(grand), Some(state) if state != 'Z'),
            "staged grandchild must be live"
        );
        {
            let mut status = 0;
            // SAFETY: WNOHANG probe only.
            let got = unsafe { libc::waitpid(grand, &mut status, libc::WNOHANG) };
            assert!(got < 0, "staged grandchild must not be our child");
        }
        // Caught (probe scaffolding): RED runs reach cleanup.
        let fired = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _fired = pinned;
        })); // Drop fires here (scope end or unwind).
             // R17-009: DISCHARGE required (not merely death) — the
             // live publisher reaps promptly; a lingering zombie past
             // the window is unresolved. R17-010: strict evidence —
             // unreadable samples keep polling and fail loud past
             // the bound.
        let retired = await_proc_gone_reaping(grand, tick, Duration::from_secs(5));
        // Cleanup (runs on RED too): tick-gated kill, poll
        // gone, reap the publisher.
        let _ = kill_tick_gated(grand, tick);
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            if proc_starttime(grand) != Ok(Some(tick)) {
                break;
            }
            assert!(Instant::now() < end, "staged grandchild must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            if parent.try_wait().expect("parent wait").is_some() {
                break;
            }
            assert!(Instant::now() < end, "publisher must exit");
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(retired, "recovered pin must retire the known grandchild");
        assert!(fired.is_ok(), "pin scope must not panic");
        eprintln!("R17007-RECOVERED retired=1");
    }

    /// R17-007: a constructor that exhausts its retry budget
    /// (None) while the explicit birth read succeeds must pass
    /// the recovered tick to the guard (late-pin) — the drop
    /// then retires the known non-child instead of ECHILDing
    /// past it.
    #[test]
    #[cfg(target_arch = "x86_64")]
    fn nonchild_recovered_pin_retires_on_drop() {
        if std::env::var("SCOPEBASE_R17007_NONCHILD").is_ok() {
            nonchild_pin_recovery_probe();
            return;
        }
        let exe = std::env::current_exe().expect("own test binary");
        let out = std::process::Command::new(exe)
            .arg("--exact")
            .arg("fixture::linux::audit::tests::nonchild_recovered_pin_retires_on_drop")
            .arg("--nocapture")
            .env("SCOPEBASE_R17007_NONCHILD", "1")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .output()
            .expect("probe child runs");
        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
        assert!(
            out.status.success(),
            "probe must retire through the recovered pin\n{stderr}"
        );
        assert!(
            stderr.contains("R17007-RECOVERED retired=1"),
            "probe must cite the retirement\n{stderr}"
        );
    }

    /// R17-007: probe body (fresh image, SCOPEBASE_R17007_MID)
    /// — mirror of the stopped-stage middleman window: freeze
    /// a grandchild (stopped ⇒ strand-forever), fail the
    /// constructor reads (EMFILE), succeed the explicit read
    /// after restore, late-pin the recovered tick, then suffer
    /// a LATER failure (the middleman sites have no pin
    /// assert — the panic comes from downstream asserts):
    /// unwind must retire the frozen grandchild. RED (no
    /// late-pin): unwind drops unpinned, ECHILDs past the
    /// stopped task. Duration 44 is unique to this test.
    #[cfg(target_arch = "x86_64")]
    fn frozen_pin_recovery_probe() {
        use std::io::BufRead as _;
        use std::time::{Duration, Instant};
        // R19003-FLAKE01: confine the table before any
        // exhaustion below (fresh image — the limit dies
        // with the probe).
        let _confined = confine_fd_table_for_exhaustion();
        let mut parent = std::process::Command::new(pair_publisher_bin())
            .arg("44")
            .arg("wait")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("publisher spawns");
        let mut line = String::new();
        std::io::BufReader::new(parent.stdout.take().expect("publisher stdout"))
            .read_line(&mut line)
            .expect("grandchild pid readable");
        // R19-001: transmitted pair (no receiver
        // first-read).
        let (grand, pre_tick) = parse_published_pair(line.trim(), "grandchild publication");
        // R18-008: custody BEFORE the freeze — the grandchild
        // pair arrives via pipe (received pid:
        // expected-identity per the R17-008 contract over the
        // transmitted birth). Any later panic (T-poll,
        // exhaustion, construction) retires through this guard
        // instead of stranding a stopped task with its publisher
        // waiting. The pin assert lands pre-stop: a staging
        // failure here leaks only RUNNING tasks (bounded
        // self-exit), never a stopped one.
        let mut outer = FixtureGuard::new_expected(grand, pre_tick);
        assert!(
            outer.tick.is_some(),
            "outer custody must pin pre-stop (stage broken otherwise)"
        );
        // Freeze (the middleman essence): stopped tasks
        // cannot exit — the number is stable for late-pin.
        // SAFETY: SIGSTOP to our own staged grandchild.
        assert_eq!(
            unsafe { libc::kill(grand, libc::SIGSTOP) },
            0,
            "grandchild freeze"
        );
        let end = Instant::now() + Duration::from_secs(5);
        loop {
            if matches!(proc_state(grand), Some(state) if state == 'T') {
                break;
            }
            assert!(Instant::now() < end, "grandchild must stop");
            std::thread::sleep(Duration::from_millis(1));
        }
        // Fail the constructor reads: exhaust through
        // construction (the retry budget expires to None).
        let mut held = Vec::new();
        while let Ok(file) = std::fs::File::open("/dev/null") {
            held.push(file);
        }
        assert!(!held.is_empty(), "exhaustion must consume fds");
        let mid_guard = FixtureGuard::new(grand);
        assert!(
            mid_guard.tick.is_none(),
            "construction must fail under EMFILE (stage broken otherwise)"
        );
        drop(held);
        // The explicit birth read succeeds after restore.
        let tick = proc_starttime(grand)
            .expect("grandchild stat readable")
            .expect("grandchild present");
        // R17-007: pin-before-panic — late-pin the recovered
        // tick so the later unwind retires the frozen
        // grandchild (stopped ⇒ the number is stable — the pin
        // cannot authorize a replacement). R18-005: the pin
        // lands before the diagnostic (a failing write must
        // never precede custody).
        let mut mid_guard = mid_guard;
        if mid_guard.tick.is_none() {
            mid_guard.pin(tick);
            eprintln!("R17007 construction pin missed; late-pinned recovered tick");
        }
        let fired = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = mid_guard;
            panic!("R17007 injected later failure (downstream assert)");
        }));
        assert!(fired.is_err(), "injection must unwind");
        // Observe before cleanup: the frozen grandchild must
        // be gone (signaled + reaped by the waiting publisher).
        // R17-010: strict evidence — unreadable samples keep
        // polling and fail loud past the bound.
        let retired = await_proc_gone_reaping(grand, tick, Duration::from_secs(5));
        // Cleanup (runs on RED too): tick-gated kill (works
        // on stopped tasks), poll gone, reap publisher. The outer
        // stays armed through it (a cleanup-loop panic with
        // the grandchild still stopped must still retire —
        // the tick-gated drop stays silent once gone, so the
        // late disarm cannot double-retire).
        let _ = kill_tick_gated(grand, tick);
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            if proc_starttime(grand) != Ok(Some(tick)) {
                break;
            }
            assert!(Instant::now() < end, "staged grandchild must die");
            std::thread::sleep(Duration::from_millis(10));
        }
        let end = Instant::now() + Duration::from_secs(10);
        loop {
            if parent.try_wait().expect("parent wait").is_some() {
                break;
            }
            assert!(Instant::now() < end, "publisher must exit");
            std::thread::sleep(Duration::from_millis(10));
        }
        // R18-008: teardown complete (grandchild proven gone,
        // publisher reaped) — stand the outer down.
        outer.disarm();
        assert!(retired, "recovered pin must retire the frozen grandchild");
        eprintln!("R17007-MRECOVERED retired=1");
    }

    /// R17-007: stopped-stage twin — a frozen grandchild whose
